script:
await step('Kiểm tra màn hình Tổng quan Bảo trì (/maintenance/dashboard)', async () => {
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  const body = await page.locator('body').innerText();
  assert(body.length > 50, 'Trang Tổng quan Bảo trì không có nội dung');
  ctx.log('Đã mở Tổng quan Bảo trì tại: ' + page.url());
});

await step('Điều hướng sang Báo cáo Số liệu vận hành (/maintenance/report/operating)', async () => {
  await page.goto('https://tasks.zuizui.io/maintenance/report/operating', { waitUntil: 'domcontentloaded' });
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  assert(/\/maintenance\/report\/operating/.test(page.url()), 'Chưa vào được trang Số liệu vận hành Bảo trì');
});

await step('Kiểm tra nội dung báo cáo Số liệu vận hành hiển thị đúng', async () => {
  const txt = await page.locator('body').innerText();
  assert(/Số liệu vận hành|Số lượng phiếu|Thời gian/i.test(txt), 'Không tìm thấy tiêu đề hoặc biểu đồ trên trang Số liệu vận hành');
  ctx.log('Trang Số liệu vận hành Bảo trì hiển thị đầy đủ.');
});
